from taf.ul.ettf.msg_capture.expectations import ExpectationsManager
from taf.ul.ettf.ta_matchers.matchers import Any, Contains
from taf.ul.ettf.typed.typed import typed
from taf.ul.ettf.msg_capture.expectation_builders.detailed import UniqueMessageDetail
from taf.ul.ettf.msg_capture.expectation_builders import WithStoredArgument
from taf.ul.ettf.msg_capture.storage import AppendToList


def bearer_res(erab_id):
    return Any({
        'ProtocolIE-SingleContainer': Any({
            'value': Any({
                'E-RABSetupItemBearerSURes': Any({
                    'e-RAB-ID': erab_id
                })
            })
        })
    })


def ics_bearers_res(bearers_container, bearers_aggregator=Contains):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'E-RABSetupListBearerSURes': bearers_aggregator(*bearers_container)
            })
        })
    })


def bearer_req(erab_id):
    return Any({
        'ProtocolIE-SingleContainer': Any({
            'value': Any({
                'E-RABToBeSetupItemCtxtSUReq': Any({
                    'e-RAB-ID': erab_id
                })
            })})
    })


def ics_bearers_req(bearers_container, bearers_aggregator=Contains):
    return Any({
        'ProtocolIE-Field': Any({
            'value': Any({
                'E-RABToBeSetupListCtxtSUReq': bearers_aggregator(*bearers_container)
            })
        })
    })


class bearers(ExpectationsManager):
    @typed(erab_id=int)
    def with_bearer(self, erab_id):
        self.store('S1AP_ICS_Bearers', bearer_res(erab_id), AppendToList)
        self.append_expectation(UniqueMessageDetail('protocolIEs', WithStoredArgument(ics_bearers_res, 'S1AP_ICS_Bearers'), Contains))

    @typed(erab_id=int)
    def with_bearer_req(self, erab_id):
        self.store('S1AP_ICS_Bearers', bearer_req(erab_id), AppendToList)
        self.append_expectation(UniqueMessageDetail('protocolIEs', WithStoredArgument(ics_bearers_req, 'S1AP_ICS_Bearers'), Contains))
